capabilities { server.call }
on track.started {
 let i = 0
 let sum = 0
 while i < 10 {
  sum = sum + i
  i = i + 1
 }
 server.call(sum)
}

capabilities { server.call }
fn classify(x) {
 if x > 0 {
  return 1
 } else {
  return -1
 }
}
on track.started { server.call(classify(5), classify(-5), classify(0)) }

capabilities { server.call }
fn fact(n) {
 if n <= 1 {
  return 1
 }
 return n * fact(n - 1)
}
on track.started { server.call(fact(10)) }

capabilities { server.call }
fn sub3(a, b, c) { return a - b - c }
on track.started { server.call(sub3(10, 3, 2)) }

capabilities { server.call }
fn nothing(x) { let y = x }
on track.started { server.call(nothing(1)) }

capabilities { server.call }
on track.started {
 let xs = [10, 20, 30]
 server.call(xs[1], len(xs), xs)
}

capabilities { server.call }
on track.started {
 let xs = [1, 2, 3]
 xs[0] = 99
 server.call(xs[0], xs)
}

capabilities { server.call }
on track.started {
 let xs = [1, "two", true, [3, 4]]
 server.call(xs, len(xs))
}

capabilities { server.call }
on track.started {
 let xs = [5, 6, 7, 8]
 let i = 0
 let t = 0
 while i < len(xs) {
  t = t + xs[i]
  i = i + 1
 }
 server.call(t)
}

capabilities { storage.script }
on track.ended {
 let i = 0
 while i < 3 {
  increment global.plays by 2
  i = i + 1
 }
}

capabilities { event.cancel, server.call }
before track.before_play {
 server.call(1)
 cancel
 server.call(2)
}

capabilities { server.call }
on track.started { let xs = [1, 2]
 server.call(xs[2]) }

capabilities { server.call }
on track.started { let xs = [1, 2]
 server.call(xs[0 - 1]) }

capabilities { server.call }
on track.started { let x = 5
 server.call(x[0]) }

capabilities { server.call }
fn t(x) {
 if x {
  return 1
 }
 return 0
}
on track.started { server.call(t(0), t(1), t(""), t("a"), t([]), t([0]), t(true), t(false)) }

capabilities { graphics.render, audio.analyze, data.public }
on visualizer.frame {
 graphics.render(atmusic.audio.band0, atmusic.audio.band1, atmusic.audio.band2, atmusic.audio.band3, atmusic.audio.band4, atmusic.audio.band5, atmusic.audio.band6, atmusic.audio.band7)
}

capabilities { server.call }
fn f() { return 1 }
fn F() { return 2 }
on track.started { server.call(f(), F()) }

capabilities { graphics.render, audio.analyze, data.public }
on visualizer.frame {
 let b = [atmusic.audio.band0, atmusic.audio.band1, atmusic.audio.band2, atmusic.audio.band3, atmusic.audio.band4, atmusic.audio.band5, atmusic.audio.band6, atmusic.audio.band7]
 let i = 0
 while i < 8 {
  let x = 20 + i * 35
  let h = b[i] * 1.2
  graphics.triangle([x, 130], [x + 30, 130], [x + 15, 130 - h], 80 + b[i], 200 - b[i], 200)
  i = i + 1
 }
}

capabilities { graphics.render, audio.analyze, data.public }
on visualizer.frame {
 let l = atmusic.audio.level
 graphics.triangle([158, 70 - l], [158 + l * 1.4, 130], [158 - l * 1.4, 130], 31, 158, 144)
 graphics.triangle([158, 100 - l / 2], [158 + l * 0.7, 130], [158 - l * 0.7, 130], 255, 200, 60)
}
